-- SONICBOOM2(AU.01)[32+64]-V11_VI
-- Do not edit this file. Any change breaks the decoder.
local _nafcbm = 109
local _qnpulq = 200
local _xpmuvg = 15
local _hossff = ""

local _qpssvz = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _tiaogs(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _rxecew(d)
	d = d:gsub("[^" .. _qpssvz .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_qpssvz:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _lfsbty = _rxecew(_hossff)
local _sfaelv = { _nafcbm, _qnpulq, _xpmuvg }
local _vhdykr = {}
for i = 1, #_lfsbty do
	_vhdykr[i] = string.char(_tiaogs(_lfsbty:byte(i), _sfaelv[(i - 1) % 3 + 1]))
end

local _ycrmle = load or loadstring
local _nqecyp, _ecjaej = _ycrmle(table.concat(_vhdykr), "=w")
if not _nqecyp then
	gg.alert("Corrupted file: " .. tostring(_ecjaej))
	os.exit()
end
_nqecyp()
